import{_ as i,o as a,c as s,a2 as t}from"./chunks/framework.DncwoWA8.js";const o="/projects/ai-skills/diagrams/skill-groups.svg",g=JSON.parse('{"title":"Find a skill","description":"","frontmatter":{"title":"Find a skill"},"headers":[],"relativePath":"skills/index.md","filePath":"skills/index.md"}'),r={name:"skills/index.md"};function l(n,e,c,d,p,h){return a(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="find-a-skill" tabindex="-1">Find a skill <a class="header-anchor" href="#find-a-skill" aria-label="Permalink to &quot;Find a skill&quot;">​</a></h1><p>The catalog contains <strong>28 skills</strong>: 20 local entries and 8 remote-source entries. Search by an exact skill name or start with your task.</p><p><img src="'+o+'" alt="The collection&#39;s six groups include local and external skills; grouping is not a runtime dependency."></p><p><a href="/projects/ai-skills/diagrams/skill-groups.html" class="vp-raw">Open interactive diagram</a> · <a href="/projects/ai-skills/diagrams/skill-groups.svg">Download SVG</a> · <a href="/projects/ai-skills/diagram-sources/skill-groups.json">Editable candidate</a></p><h2 id="productivity" tabindex="-1"><a href="/projects/ai-skills/groups/productivity.html">Productivity</a> <a class="header-anchor" href="#productivity" aria-label="Permalink to &quot;[Productivity](/groups/productivity)&quot;">​</a></h2><p>Research questions, shape initiatives, specify behavior, plan tasks, and learn from results.</p><ul><li><a href="/projects/ai-skills/skills/initiative.html"><code>initiative</code></a> — Turn an idea or research into an agreed brief covering the problem, outcomes, scope, constraints, and success measures.</li><li><a href="/projects/ai-skills/skills/research.html"><code>research</code></a> — Research a question, compare alternatives, or investigate feasibility; report verified evidence, uncertainty, and limits.</li><li><a href="/projects/ai-skills/skills/specify.html"><code>specify</code></a> — Turn agreed decisions into a compact specification with observable behavior, acceptance criteria, constraints, and test boundaries.</li><li><a href="/projects/ai-skills/skills/plan-tasks.html"><code>plan-tasks</code></a> — Divide an agreed specification or clear scope into bounded, verifiable tasks with explicit dependencies and completion evidence.</li><li><a href="/projects/ai-skills/skills/retro.html"><code>retro</code></a> — Review a bounded work period for evidence-backed process improvements, including workflow, instructions, tools, and handoffs.</li><li><a href="/projects/ai-skills/skills/grill-me.html"><code>grill-me</code></a> — A relentless interview to sharpen a plan or design.</li><li><a href="/projects/ai-skills/skills/grilling.html"><code>grilling</code></a> — Stress-test a plan or decision through an explicit interview.</li><li><a href="/projects/ai-skills/skills/wait-what.html"><code>wait-what</code></a> — Explain the current proposal again with simpler language and missing context.</li></ul><h2 id="coding" tabindex="-1"><a href="/projects/ai-skills/groups/coding.html">Coding</a> <a class="header-anchor" href="#coding" aria-label="Permalink to &quot;[Coding](/groups/coding)&quot;">​</a></h2><p>Scaffold, implement, test, diagnose, simplify, and review code.</p><ul><li><a href="/projects/ai-skills/skills/coding.html"><code>coding</code></a> — Design, implement, refactor, review, or test code under project conventions, risk-based security, and behavior-focused checks.</li><li><a href="/projects/ai-skills/skills/coding-with-rules.html"><code>coding-with-rules</code></a> — Language-aware coding: resolve the base workflow, then select rules for the languages and file extensions being changed.</li><li><a href="/projects/ai-skills/skills/scaffold.html"><code>scaffold</code></a> — Create source skeletons for an approved feature, validate their structure, and stop before implementing behavior.</li><li><a href="/projects/ai-skills/skills/code-review.html"><code>code-review</code></a> — Review the changes since a fixed point (commit, branch, tag, or merge-base) along two axes: Standards (does the code follow this repo&#39;s documented coding standards?) and Spec (does the code match what the originating issue/spec asked for?). Runs both reviews in parallel sub-agents and reports them side by side. Use when the user wants to review a branch, a PR, work-in-progress changes, or asks to &quot;review since X&quot;.</li><li><a href="/projects/ai-skills/skills/systematic-debugging.html"><code>systematic-debugging</code></a> — Diagnose bugs, failing tests, regressions, flaky behavior, and unexpected results through evidence, root-cause tracing, and single-hypothesis experiments before proposing fixes. Use for debugging in any language, including failures across component or environment boundaries.</li><li><a href="/projects/ai-skills/skills/tdd.html"><code>tdd</code></a> — Test-driven development. Use when the user wants to build features or fix bugs test-first, mentions &quot;red-green-refactor&quot;, or wants integration tests.</li><li><a href="/projects/ai-skills/skills/debloat.html"><code>debloat</code></a> — Prevent overengineering during design; simplify existing code, configuration, or dependencies while preserving required behavior, contracts, security, and operational needs.</li></ul><h2 id="documentation" tabindex="-1"><a href="/projects/ai-skills/groups/documentation.html">Documentation</a> <a class="header-anchor" href="#documentation" aria-label="Permalink to &quot;[Documentation](/groups/documentation)&quot;">​</a></h2><p>Write technical documentation and explanations, or create editable and interactive diagrams.</p><ul><li><a href="/projects/ai-skills/skills/asd-ste100-technical.html"><code>asd-ste100-technical</code></a> — Technical writing: use ASD-STE100-inspired plain language for software responses and documentation.</li><li><a href="/projects/ai-skills/skills/caveman.html"><code>caveman</code></a> — Concise communication that preserves complete technical substance.</li><li><a href="/projects/ai-skills/skills/document-project.html"><code>document-project</code></a> — Maintain task-based developer documentation during implementation; create or refactor VitePress/MkDocs documentation within approved scope.</li><li><a href="/projects/ai-skills/skills/unslop.html"><code>unslop</code></a> — Remove AI-generated prose patterns while preserving meaning.</li><li><a href="/projects/ai-skills/skills/excalidraw.html"><code>excalidraw</code></a> — Generate PNG or SVG diagrams with local Excalidraw rendering. Use for project structure, component relationships, workflows, or revisions to an existing diagram. Retain scene JSON as editable source and deliver images first.</li><li><a href="/projects/ai-skills/skills/archify.html"><code>archify</code></a> — Generate validated interactive HTML diagrams or one-page explainers with Archify, including architecture, workflows, Mermaid input, and image/SVG/WebM exports.</li></ul><h2 id="agentic-work" tabindex="-1"><a href="/projects/ai-skills/groups/agentic-work.html">Agentic work</a> <a class="header-anchor" href="#agentic-work" aria-label="Permalink to &quot;[Agentic work](/groups/agentic-work)&quot;">​</a></h2><p>Manage selected agent skills and write agent-facing instructions.</p><ul><li><a href="/projects/ai-skills/skills/writing-for-agents.html"><code>writing-for-agents</code></a> — Writing documents for agents. Use when creating or editing skills, or modifying AGENTS.md or CLAUDE.md.</li><li><a href="/projects/ai-skills/skills/sync-my-skills.html"><code>sync-my-skills</code></a> — Synchronize project skills and agent instructions through a guided, approved plan.</li></ul><h2 id="utility" tabindex="-1"><a href="/projects/ai-skills/groups/utility.html">Utility</a> <a class="header-anchor" href="#utility" aria-label="Permalink to &quot;[Utility](/groups/utility)&quot;">​</a></h2><p>Initialize projects, isolate changes, and clean approved workspaces.</p><ul><li><a href="/projects/ai-skills/skills/init-project.html"><code>init-project</code></a> — Initialize or adopt project foundations, TypeScript tooling, or Godot GDScript tooling only when explicitly requested.</li><li><a href="/projects/ai-skills/skills/isolated-workspace.html"><code>isolated-workspace</code></a> — Create a dedicated task branch or bookmark before repository edits. Choose the current checkout or an isolated Git worktree or Jujutsu workspace; ask the user when the location is unclear.</li><li><a href="/projects/ai-skills/skills/cleanup-workspaces.html"><code>cleanup-workspaces</code></a> — Audit integrated Git/Jujutsu workspaces, stale registrations, or authorized temporary lanes; apply only an approved exact cleanup plan.</li></ul><h2 id="unpolished" tabindex="-1"><a href="/projects/ai-skills/groups/unpolished.html">Unpolished</a> <a class="header-anchor" href="#unpolished" aria-label="Permalink to &quot;[Unpolished](/groups/unpolished)&quot;">​</a></h2><p>Coordinate bounded agent work and audit instruction changes.</p><ul><li><a href="/projects/ai-skills/skills/instruction-maintenance.html"><code>instruction-maintenance</code></a> — Audit instruction drift, routing, and skill metadata; propose exact changes for human approval before mutation.</li><li><a href="/projects/ai-skills/skills/subagent-orchestration.html"><code>subagent-orchestration</code></a> — Before delegating, bound child-agent work, assign read/write lanes, integrate results, review, validate, and clean temporary lanes.</li></ul><p>The YAML catalog is the only authored inventory. Grouping and learning prose reference its IDs; generated pages do not define a second installable collection. See the <a href="/projects/ai-skills/reference/catalog.html">catalog reference</a>.</p>',23)])])}const m=i(r,[["render",l]]);export{g as __pageData,m as default};
